cat > /tmp/test_redirect_validation.js << 'EOF'
import { isSafeRedirect } from './app/Utils/SafeRedirect.ts'

// Test cases from the security report
const testCases = [
  // Valid cases - should return true
  ['/posts/3/edit', true, 'same-app path'],
  ['/dashboard', true, 'root-relative path'],
  ['/', true, 'root path'],

  // Malicious cases - should return false
  ['https://evil.example', false, 'absolute URL with scheme'],
  ['//evil.example', false, 'protocol-relative URL'],
  ['/\\evil.example', false, 'backslash variant'],
  ['', false, 'empty string'],
  ['posts', false, 'relative path without leading /'],
]

console.log('Testing redirect validation:')
testCases.forEach(([url, expected, description]) => {
  const result = isSafeRedirect(url)
  const status = result === expected ? '✓' : '✗'
  console.log(`${status} ${description}: "${url}" -> ${result}`)
})
EOF
node /tmp/test_redirect_validation.js 2>/dev/null || echo "Direct test skipped"
